import csv

DEFAULT_LIMIT = 500


def import_readings(csv_path):
    rows = []
    with open(csv_path, newline="", encoding="utf-8") as source:
        for row in csv.DictReader(source):
            rows.append({
                "employee_id": row["staff_code"],
                "recorded_on": row["screen_date"],
                "reading": row["reading"],
            })
            if len(rows) >= DEFAULT_LIMIT:
                break
    return rows

