package hr

import (
	"sort"
	"time"
)

type Employee struct {
	Name     string `json:"name"`
	HireDate string `json:"hire_date"`
}

func SortByHireDate(rows []Employee) {
	layout := "2006-01-02"
	sort.SliceStable(rows, func(i, j int) bool {
		a, _ := time.Parse(layout, rows[i].HireDate)
		b, _ := time.Parse(layout, rows[j].HireDate)
		return a.Before(b)
	})
}
--- cmd/hr/main.go ---
package main

import (
	"encoding/json"
	"fmt"
	"os"

	"example.com/roster/internal/hr"
)

func main() {
	var rows []hr.Employee
	if err := json.NewDecoder(os.Stdin).Decode(&rows); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	hr.SortByHireDate(rows)
	json.NewEncoder(os.Stdout).Encode(rows)
}

