import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import java.util.List;

@RestController
class BookController {
    private final ObjectMapper json = new ObjectMapper();

    @GetMapping("/books")
    String books() throws JsonProcessingException {
        List<Book> rows = List.of(new Book("Pine", 8), new Book("Elm", 13), new Book("Fir", 5));
        return json.writeValueAsString(rows.subList(0, Math.min(rows.size(), 2)));
    }

    record Book(String name, int stock) {}
}

