package acl

import (
	"bufio"
	"net"
	"os"
	"strings"
)

type Issue struct {
	Line  int
	Value string
}

func ValidateFile(path string) ([]Issue, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	var issues []Issue
	scan := bufio.NewScanner(f)
	line := 0
	for scan.Scan() {
		line++
		value := strings.TrimSpace(scan.Text())
		if value != "" && net.ParseIP(value) == nil {
			issues = append(issues, Issue{Line: line, Value: value})
		}
	}
	return issues, scan.Err()
}

