    public static long gcd(long a, long b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            long remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }

    public static void main(String[] args) {
        System.out.println(gcd(gcd(PRIMARY_BALANCE, RESERVE_BALANCE), CLEARING_BALANCE));
    }
}

