#[derive(Debug)]
pub enum Token {
    Number(String),
    Identifier(String),
    Operator(char),
}

pub fn tokenize(input: &str) -> Vec<Token> {
    input.split_whitespace()
        .filter_map(|part| {
            if part.chars().all(|c| c.is_ascii_digit()) {
                Some(Token::Number(part.to_string()))
            } else if part.len() == 1 {
                Some(Token::Operator(part.chars().next().unwrap()))
            } else if part.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
                Some(Token::Identifier(part.to_string()))
            } else {
                None
            }
        })
        .collect()
}

