#include <stdio.h>
#include <stdlib.h>
#include "settings.h"

struct Node { int value; struct Node *next; };

static struct Node *delete_value(struct Node *head, int value) {
    struct Node **link = &head;
    while (*link) {
        if ((*link)->value == value) {
            *link = (*link)->next;
            return head;
        }
        link = &(*link)->next;
    }
    return head;
}

int main(void) {
    const int seed_count = 5, remove_value = 5, print_limit = 4;
    struct Node *head = NULL, **tail = &head;
    for (int i = 0; i < seed_count; ++i) {
        struct Node *node = malloc(sizeof *node);
        if (!node) return 1;
        node->value = 3 + i;
        node->next = NULL;
        *tail = node;
        tail = &node->next;
    }
    head = delete_value(head, remove_value);
    printf("list:");
    int shown = 0;
    for (struct Node *node = head; node && shown < print_limit; node = node->next) {
        printf(" %d", node->value);
        ++shown;
    }
    putchar('\n');
