import re

UNITS = {"cup", "cups", "tbsp", "tsp", "g", "ml"}

def parse_ingredient(line):
    match = re.fullmatch(
        r"\s*(\d+(?:\s+\d+/\d+|\.\d+)?)\s+([A-Za-z]+)\s+(.+?)\s*",
        line,
    )
    if not match:
        raise ValueError(f"Cannot parse ingredient: {line!r}")
    quantity, unit, name = match.groups()
    if unit.lower() not in UNITS:
        name = f"{unit} {name}"
        unit = ""
    return quantity, unit.lower(), name.strip()

