from datetime import datetime, timedelta

def find_gaps(timestamps):
    times = [datetime.fromisoformat(value) for value in timestamps]
    limit = timedelta(minutes=5)
    return [
        (left.isoformat(timespec="minutes"), right.isoformat(timespec="minutes"))
        for left, right in zip(times, times[1:])
        if right - left > limit
    ]

