def order_targets(dependencies):
    remaining = {name: set(items) for name, items in dependencies.items()}
    result = []
    while remaining:
        ready = next((name for name, items in remaining.items() if not items), None)
        if ready is None:
            raise ValueError("dependency cycle")
        result.append(ready)
        del remaining[ready]
        for items in remaining.values():
            items.discard(ready)
    return result


if __name__ == "__main__":
    print(" ".join(order_targets(DEPENDENCIES)))

