function weeklySummary(rows) {
  const totals = {};
  for (const { site, decayKpa } of rows) {
    const item = totals[site] ??= { normal: 0, outOfRange: 0 };
    if (decayKpa >= LOW_KPA && decayKpa <= HIGH_KPA) item.normal++;
    else item.outOfRange++;
  }
